213	func ParsePartialRegistryURL(registryURL string, assumedResourceType string) (*URLInfo, error) {
214		var version *semver.Version
215		nameSpec := registryURL
216		if idx := strings.LastIndex(registryURL, "@"); idx != -1 {
217			versionStr := registryURL[idx+1:]
218			if versionStr == "" {
219				return nil, &MissingVersionAfterAtSignError{URL: registryURL}
220			}
